```
:root {
  --bg-color: #0a0a0c;
  --sidebar-bg: #111114;
  --card-bg: #1a1a1e;
  --accent-color: #7c4dff;
  --accent-gradient: linear-gradient(135deg, #7c4dff 0%, #448aff 100%);
  --text-primary: #e0e0e0;
  --text-secondary: #a0a0a0;
  --border-color: #2a2a2e;
  --glass-bg: rgba(26, 26, 30, 0.8);
  --font-family: 'Outfit', sans-serif;
}

.hidden {
  display: none !important;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: var(--font-family);
  background-color: var(--bg-color);
  color: var(--text-primary);
  height: 100vh;
  width: 100vw;
  overflow: hidden;
}

#app {
  display: grid;
  grid-template-columns: 260px 1fr 300px;
  height: 100vh;
  width: 100vw;
}

/* Sidebar Styling */
.sidebar {
  background-color: var(--sidebar-bg);
  border-right: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  padding: 1.5rem;
  height: 100%;
}

.sidebar-header h1 {
  font-size: 1.5rem;
  font-weight: 600;
  margin-bottom: 2rem;
}

.sidebar-header h1 span {
  background: var(--accent-gradient);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.status-indicators {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 1rem;
}

.status-indicator {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.75rem;
  color: var(--text-secondary);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.status-indicator .dot {
    margin-left: 0;
}

.header-actions {
  display: flex;
  gap: 8px;
  margin-bottom: 1.5rem;
}

.btn-primary {
  flex: 1;
  padding: 0.8rem;
  border-radius: 12px;
  border: none;
  background: var(--accent-gradient);
  color: white;
  font-weight: 600;
  cursor: pointer;
  transition: transform 0.2s, opacity 0.2s;
}

.btn-danger-outline {
  padding: 0.8rem;
  border-radius: 12px;
  border: 1px solid rgba(244, 67, 54, 0.5);
  background: rgba(244, 67, 54, 0.1);
  color: #f44336;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
}

.btn-danger-outline:hover {
  background: #f44336;
  color: white;
}

.chat-list {
  flex: 1;
  overflow-y: auto;
}

.chat-item {
  padding: 0.8rem;
  border-radius: 8px;
  margin-bottom: 0.5rem;
  cursor: pointer;
  transition: background 0.2s;
  color: var(--text-secondary);
  font-size: 0.9rem;
  border: 1px solid transparent;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.chat-item.active {
  background: var(--card-bg);
  border-color: var(--accent-color);
  color: var(--text-primary);
}

.chat-item-main { display: flex; align-items: center; justify-content: space-between; flex: 1; min-width: 0; }
.name-row { display: flex; flex-direction: column; min-width: 0; flex: 1; }
.session-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

.corrupted-badge {
  font-size: 0.6rem;
  background: #f44336;
  color: white;
  padding: 1px 4px;
  border-radius: 4px;
  width: fit-content;
  font-weight: 800;
  margin-top: 2px;
}

.dot { margin-left: 10px; width: 8px; height: 8px; background-color: #666; border-radius: 50%; flex-shrink: 0;}
.dot.live { background-color: #4caf50; box-shadow: 0 0 8px #4caf50; }
.dot.dead { background-color: #f44336; box-shadow: 0 0 8px #f44336; }
.dot.busy { background-color: #ff9800; box-shadow: 0 0 8px #ff9800; animation: pulse 1.5s infinite; }
.dot.error { background-color: #f44336; box-shadow: 0 0 8px #f44336; }

.chat-item.corrupted {
  background: rgba(244, 67, 54, 0.08);
  border-color: rgba(244, 67, 54, 0.3);
}

.chat-item.corrupted:hover {
  background: rgba(244, 67, 54, 0.15);
}

.chat-item.active.corrupted {
  background: rgba(244, 67, 54, 0.2);
  border-color: #f44336;
}

.chat-item.corrupted .session-name {
  color: #ff8a80;
}

@keyframes pulse { 0% { opacity: 1; transform: scale(1); } 50% { opacity: 0.5; transform: scale(1.2); } 100% { opacity: 1; transform: scale(1); } }

/* Main Content area */
.main-content {
  display: flex;
  flex-direction: column;
  height: 100vh;
  min-width: 0;
}

.top-nav {
  height: auto;
  min-height: 80px;
  border-bottom: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  padding: 1rem 2rem;
  gap: 2rem;
  flex-wrap: wrap;
}


select, input[type="text"] {
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  color: var(--text-primary);
  padding: 0.6rem 1rem;
  border-radius: 10px;
  font-family: inherit;
  font-size: 0.9rem;
  outline: none;
  transition: all 0.2s;
}

select:hover, input[type="text"]:focus {
  border-color: var(--accent-color);
  box-shadow: 0 0 0 2px rgba(124, 77, 255, 0.2);
}

.config-group {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.config-group label {
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.folder-selector {
  flex: 1;
  max-width: 500px;
}

.input-group {
    display: flex;
    gap: 0.5rem; /* Espacio entre el input y el botón */
}

.input-group #folder-path {
  flex-grow: 1; /* Permite que el input ocupe el espacio restante */
  width: auto; /* Sobrescribe width: 100% */
}

.folder-actions { /* Esto ya no es necesario si agrupamos, pero lo dejamos por si hay dependencia */
    display: flex;
    gap: 8px;
}

.btn-icon {
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: 10px;
  width: 38px;
  height: 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.2s;
}

.btn-icon:hover {
  background: var(--border-color);
  border-color: var(--accent-color);
}

.btn-run {
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: 10px;
  color: var(--text-secondary);
  padding: 0 1.2rem;
  font-family: inherit;
  font-size: 0.8rem;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.2s;
  height: 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  letter-spacing: 0.5px;
}

.btn-run:hover {
  border-color: #2ea44f;
  color: #2ea44f;
  background: rgba(46, 164, 79, 0.05);
}

.btn-run:active {
  transform: translateY(1px);
}

.btn-git {
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: 10px;
  color: var(--text-secondary);
  width: 44px;
  height: 38px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.2s;
}

.btn-git:hover {
  background: #24292e;
  border-color: #fff;
  color: #fff;
}

.git-input-group {
    display: flex;
    gap: 8px;
    align-items: center;
}

.git-commit-wrapper {
    display: flex;
    gap: 8px;
    background: var(--card-bg);
    border: 1px solid var(--border-color);
    padding: 2px 8px 2px 2px;
    border-radius: 12px;
    animation: slideInRight 0.3s ease-out;
}

@keyframes slideInRight {
    from { opacity: 0; transform: translateX(20px); }
    to { opacity: 1; transform: translateX(0); }
}

.git-commit-wrapper input {
    border: none;
    background: transparent;
    width: 200px;
    font-size: 0.85rem;
}

.git-commit-wrapper input:focus {
    box-shadow: none;
}

.btn-git-confirm {
    background: #2ea44f;
    color: white;
    border: none;
    border-radius: 8px;
    padding: 4px 12px;
    font-size: 0.75rem;
    font-weight: 700;
    cursor: pointer;
    transition: filter 0.2s;
}

.btn-git-confirm:hover {
    filter: brightness(1.1);
}

.toggle-group {

  display: flex;
  background: #000;
  padding: 4px;
  border-radius: 12px;
  border: 1px solid var(--border-color);
}

.btn-toggle {
  padding: 6px 14px;
  border: none;
  background: none;
  color: var(--text-secondary);
  font-size: 0.8rem;
  font-weight: 600;
  cursor: pointer;
  border-radius: 10px;
  transition: all 0.2s;
}

.btn-toggle.active {
  background: var(--accent-gradient);
  color: white;
  box-shadow: 0 2px 8px rgba(124, 77, 255, 0.3);
}

.main-view {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0; /* Crucial para scroll */
  background: radial-gradient(circle at top right, #1a1a2e 0%, transparent 40%);
}

.tabs-nav {
  background: var(--sidebar-bg);
  display: flex;
  padding: 0.5rem 1rem 0;
  border-bottom: 1px solid var(--border-color);
  gap: 0.5rem;
  min-height: 48px;
  align-items: flex-end;
}

.tab {
  padding: 0.6rem 1.2rem;
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  border-bottom: none;
  border-top-left-radius: 10px;
  border-top-right-radius: 10px;
  font-size: 0.85rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 0.8rem;
  transition: all 0.2s;
  color: var(--text-secondary);
}

.tab:hover { background: #232328; }
.tab.active { background: var(--bg-color); color: var(--accent-color); border-top: 2px solid var(--accent-color); }

.add-tab {
    background: var(--accent-gradient);
    color: white !important;
    font-size: 1.4rem;
    font-weight: bold;
    width: 44px;
    height: 38px;
    justify-content: center;
    border: none;
    margin-right: 1.5rem; /* Separador del botón + de las pestañas */
    border-radius: 8px !important;
    align-self: center;
    margin-bottom: 4px;
}
.add-tab:hover { transform: scale(1.05); filter: brightness(1.1); }

.tab-content {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0; /* Crucial para scroll */
  padding: 1.5rem;
  position: relative;
}

/* CHAT MESSAGES SCROLL AREA */
.chat-messages {
  flex: 1;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  padding-right: 10px;
  min-height: 0;
}

.chat-messages::-webkit-scrollbar { width: 6px; }
.chat-messages::-webkit-scrollbar-thumb { background: var(--border-color); border-radius: 10px; }

.message {
  max-width: 85%;
  padding: 1rem 1.5rem;
  border-radius: 18px;
  line-height: 1.5;
  word-wrap: break-word;
}

.message.user { align-self: flex-end; background: var(--accent-gradient); color: white; }
.message.agent { align-self: flex-start; background: var(--card-bg); border: 1px solid var(--border-color); }
.message.agent p { margin-bottom: 0.8rem; }
.message.agent p:last-child { margin-bottom: 0; }
.message.agent strong { color: #fff; font-weight: 600; }
.message.agent ul, .message.agent ol { margin-left: 1.2rem; margin-bottom: 0.8rem; }
.message.agent li { margin-bottom: 0.3rem; }
.message.agent h1, .message.agent h2, .message.agent h3 { margin: 1rem 0 0.5rem; color: var(--accent-color); }
.message.agent pre { background: #000; padding: 1rem; border-radius: 8px; margin: 1rem 0; overflow-x: auto; border: 1px solid var(--border-color); }
.message.agent code { font-family: 'Consolas', monospace; background: rgba(0,0,0,0.3); padding: 0.2rem 0.4rem; border-radius: 4px; font-size: 0.9em; }
.message.agent pre code { background: none; padding: 0; }

/* INPUT AREA FIXED AT BOTTOM */
.input-area {
  padding: 1rem 0;
  flex-shrink: 0;
}

textarea {
  flex: 1;
  background: none;
  border: none;
  color: var(--text-primary);
  resize: vertical; /* Permitir resize manual si se desea */
  font-family: inherit;
  font-size: 1rem;
  outline: none;
  min-height: 60px;
  max-height: 200px;
}

/* Multimodal & Input Area Enhancements */
.input-wrapper {
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: 16px;
  padding: 0.8rem 1rem;
  display: flex;
  align-items: center; /* Alineado al centro para inputs de una línea, pero el textarea crece */
  gap: 1rem;
}

.input-actions-left, .input-actions-right {
  display: flex;
  align-items: center;
  gap: 0.8rem;
}

.mode-switch-container {
    display: flex;
    align-items: center;
    gap: 10px;
}

.mode-switch {
    position: relative;
    width: 64px;
    height: 32px;
    background: #000;
    border: 1px solid var(--border-color);
    border-radius: 20px;
    cursor: pointer;
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    display: flex;
    align-items: center;
    padding: 2px;
}

.mode-switch::before {
    content: 'AUTO';
    position: absolute;
    right: 8px;
    font-size: 8px;
    font-weight: 800;
    color: var(--text-secondary);
    transition: all 0.3s;
    opacity: 0.7;
}

.mode-switch.supervised::before {
    content: 'SUPV';
    left: 8px;
    right: auto;
}

.mode-switch-handle {
    width: 26px;
    height: 26px;
    background: var(--accent-gradient);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    box-shadow: 0 2px 8px rgba(124, 77, 255, 0.4);
    z-index: 2;
}

.mode-switch.supervised .mode-switch-handle {
    transform: translateX(32px);
    background: linear-gradient(135deg, #f44336 0%, #d32f2f 100%);
    box-shadow: 0 2px 8px rgba(244, 67, 54, 0.4);
}

.mode-icon-manual {
    font-size: 14px;
    pointer-events: none;
}

.btn-icon-subtle {
    background: rgba(255,255,255,0.05);
    border: 1px solid var(--border-color);
    border-radius: 12px;
    width: 40px;
    height: 40px;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.2rem;
    transition: all 0.2s;
    flex-shrink: 0;
}

.btn-icon-subtle:hover {
    background: rgba(124, 77, 255, 0.1);
    border-color: var(--accent-color);
    transform: translateY(-2px);
}

.btn-icon-subtle#attach-img {
    color: var(--text-secondary);
}

.btn-icon-subtle#attach-img:hover {
    color: white;
}

.mode-selector-mini {
    display: none; /* Removed the old one */
}

.image-preview-container {
  display: flex;
  gap: 10px;
  padding: 10px;
  background: rgba(0,0,0,0.2);
  border-radius: 12px;
  margin-bottom: 10px;
  overflow-x: auto;
}

.preview-item {
  position: relative;
  width: 60px;
  height: 60px;
}

.preview-item img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 8px;
  border: 1px solid var(--accent-color);
}

.remove-img {
  position: absolute;
  top: -5px;
  right: -5px;
  background: #f85149;
  color: white;
  border: none;
  border-radius: 50%;
  width: 18px;
  height: 18px;
  font-size: 12px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
}

.send-btn {
  background: var(--accent-gradient);
  border: none;
  width: 40px;
  height: 40px;
  border-radius: 10px;
  color: white;
  cursor: pointer;
}

/* File Explorer */
.file-explorer {
  background-color: var(--sidebar-bg);
  border-left: 1px solid var(--border-color);
  padding: 1.5rem;
  overflow-y: auto;
  height: 100vh;
  display: flex;
  flex-direction: column;
}

.file-explorer h3 {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 1.5rem;
}

.file-list {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.file-item {
  padding: 0.6rem 0.8rem;
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.2s;
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 0.9rem;
  color: var(--text-secondary);
  border: 1px solid transparent;
}

.file-item:hover {
  background: var(--card-bg);
  color: var(--text-primary);
  border-color: var(--border-color);
}

.file-item.directory {
  color: var(--accent-color);
  font-weight: 600;
}

.file-item.file {
  color: var(--text-primary);
}

.empty-state {
  text-align: center;
  color: var(--text-secondary);
  font-size: 0.85rem;
  margin-top: 2rem;
  font-style: italic;
  opacity: 0.7;
}

.file-action-link {
    background: var(--card-bg);
    border: 1px solid var(--border-color);
    padding: 0.8rem 1rem;
    border-radius: 12px;
    margin: 1rem 0;
    cursor: pointer;
    transition: all 0.2s;
    display: flex;
    align-items: center;
    gap: 12px;
    font-size: 0.9rem;
}

#editor-tab-content {
  background: #0d1117;
  padding: 0;
  display: flex;
  flex-direction: column;
  height: 100%;
}

.editor-header {
  padding: 0.8rem 1.5rem;
  background: #161b22;
  border-bottom: 1px solid var(--border-color);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.editor-header h3 {
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--text-secondary);
}

.pending-actions {
  display: flex;
  align-items: center;
  gap: 1rem;
}

.pending-label {
  font-size: 0.8rem;
  background: rgba(255, 152, 0, 0.1);
  color: #ff9800;
  padding: 4px 8px;
  border-radius: 4px;
  font-weight: 600;
}

.btn-success, .btn-danger {
  padding: 6px 12px;
  border: none;
  border-radius: 6px;
  color: white;
  font-size: 0.85rem;
  font-weight: 600;
  cursor: pointer;
  transition: opacity 0.2s;
}

.btn-success { background: #3fb950; }
.btn-danger { background: #f85149; }
.btn-success:hover, .btn-danger:hover { opacity: 0.8; }

.diff-stats {
  display: flex;
  gap: 1rem;
  font-size: 0.85rem;
  font-weight: 600;
}

.diff-added { color: #3fb950; }
.diff-removed { color: #f85149; }

.editor-container {
  flex: 1;
  overflow: auto;
  position: relative;
}

#editor-code {
  font-family: 'Consolas', 'Monaco', 'Courier New', monospace;
  font-size: 14px;
  line-height: 1.6;
  padding: 1.5rem;
  display: block;
  white-space: pre;
  word-wrap: normal;
  tab-size: 4;
}

/* Ensure highlight.js tokens are visible */
.hljs {
  color: #e6edf3;
  background: transparent !important;
}

/* Diff Styling */
.diff-line {
  display: block;
  width: 100%;
  padding-left: 0.5rem;
}

.diff-line.added {
  background-color: rgba(63, 185, 80, 0.15);
  border-left: 4px solid #3fb950;
}

.diff-line.removed {
  background-color: rgba(248, 81, 73, 0.15);
  border-left: 4px solid #f85149;
  text-decoration: line-through;
  opacity: 0.8;
}

.diff-marker {
  display: inline-block;
  width: 20px;
  font-weight: bold;
  opacity: 0.7;
  user-select: none;
}

/* Syntax Highlighting Tweaks */
pre code.hljs {
  padding: 0;
  background: transparent;
}

.editor-footer {
  height: 30px;
  background: #161b22;
  border-top: 1px solid var(--border-color);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0 1rem;
  font-size: 0.75rem;
  color: var(--text-secondary);
}

.editor-info {
  display: flex;
  gap: 1rem;
}

#editor-lang {
  text-transform: uppercase;
  font-weight: 600;
  color: var(--accent-color);
}
.hidden { display: none !important; }
.message.agent.thinking {
    background: var(--card-bg);
    border: 1px dashed var(--accent-color) !important;
    max-width: 300px;
}

.thinking-bubble-content {
    display: flex;
    align-items: center;
    gap: 12px;
}

.thinking-text-wrapper {
    display: flex;
    flex-direction: column;
}

.thinking-status {
    font-weight: 600;
    font-size: 0.9rem;
    color: white;
}

.thinking-subtext {
    font-size: 0.7rem;
    color: var(--text-secondary);
    text-transform: uppercase;
    letter-spacing: 1px;
}

.spinner-container {
    position: relative;
    width: 20px;
    height: 20px;
}

.spinner {
    width: 20px;
    height: 20px;
    border: 2px solid rgba(124, 77, 255, 0.1);
    border-top-color: var(--accent-color);
    border-radius: 50%;
    animation: spin 0.8s cubic-bezier(0.4, 0, 0.2, 1) infinite;
    display: block;
}



