document.addEventListener('DOMContentLoaded', () => {
    const track = document.getElementById('stickerCarousel');
    const nextBtn = document.getElementById('nextBtn');
    const prevBtn = document.getElementById('prevBtn');

    const cards = document.querySelectorAll('.sticker-card');

    // Determinar cuántas tarjetas mostrar visiblemente (en este caso, 3)
    const cardsVisible = 3; 

    // Calcular el ancho total de la 'ventana' de visualización
    const wrapper = document.querySelector('.carousel-wrapper');
    const cardWidthWithMargin = 320 + 20; // Ancho del card + margen derecho
    const totalVisibleWidth = cardsVisible * cardWidthWithMargin;

    let currentIndex = 0;
    const totalCards = cards.length;

    // Inicializar la posición del carrusel (asegurar que el ancho de visualización sea correcto)
    // Para que el carrusel parezca que solo muestra 3 elementos a la vez, 
    // ajustaremos la lógica de desplazamiento.

    /**
     * Función para actualizar la transformación CSS del carrusel.
     * Mueve el track basado en el índice de la tarjeta más a la izquierda.
     */
    function updateCarousel() {
        // Calculamos cuánto debe moverse el track en píxeles.
        // Movemos el track de forma que el elemento en el índice 'currentIndex' comience a verse alineado.
        const offset = -currentIndex * (cardsVisible * cardWidthWithMargin - 20); // -20 compensa el último margen
        track.style.transform = `translateX(${offset}px)`;

        // Habilitar/deshabilitar botones
        prevBtn.disabled = currentIndex <= 0;
        nextBtn.disabled = currentIndex >= totalCards - cardsVisible;
    }

    function goToNext() {
        if (currentIndex < totalCards - cardsVisible) {
            currentIndex++;
            updateCarousel();
        }
    }

    function goToPrev() {
        if (currentIndex > 0) {
            currentIndex--;
            updateCarousel();
        }
    }

    // Event Listeners
    nextBtn.addEventListener('click', goToNext);
    prevBtn.addEventListener('click', goToPrev);

    // Inicialización
    // Ajustamos el índice inicial para que muestre las primeras 'cardsVisible' tarjetas sin sobrepasar el límite.
    currentIndex = Math.min(0, totalCards - cardsVisible); 
    updateCarousel();


    // *** Implementación del "Pasar" Automático (Auto-Scroll) ***
    let autoScrollInterval = setInterval(() => {
        // Intentamos avanzar automáticamente, pero solo si no estamos en el final
        if (!nextBtn.disabled && currentIndex < totalCards - cardsVisible) {
            goToNext();
        }
    }, 4000); // Cambiar cada 4 segundos

    // Pausar auto-scroll al hacer hover sobre la galería
    const galleryWrapper = document.querySelector('.gallery-container');
    galleryWrapper.addEventListener('mouseenter', () => {
        clearInterval(autoScrollInterval);
    });

    // Reanudar auto-scroll al dejar de hacer hover
    galleryWrapper.addEventListener('mouseleave', () => {
        autoScrollInterval = setInterval(() => {
            if (!nextBtn.disabled && currentIndex < totalCards - cardsVisible) {
                goToNext();
            }
        }, 4000);
    });
});

