    opacity: 0.9;
    font-size: 1.1rem;
}

/* --- GALERÍA Y CARRUSEL --- */
.gallery-container {
    padding: 40px 20px;
    max-width: 1200px;
    margin: 0 auto;
    text-align: center;
}

.carousel-wrapper {
    /* Establecer un contenedor visible que limita la vista */
    overflow: hidden;
    margin-bottom: 20px;
    padding: 10px 0;
    border: 1px solid #ddd;
    border-radius: 10px;
    background-color: #fff;
    box-shadow: var(--shadow-light);
}

.carousel-track {
    display: flex;
    transition: transform 0.5s ease-in-out; /* Animación principal del carrusel */
    width: fit-content; /* Permite que el track sea tan ancho como sus hijos */
}

.sticker-card {
    flex: 0 0 320px; /* Cada tarjeta ocupa un ancho fijo de 320px */
    background-color: #ffffff;
    border-radius: 12px;
    box-shadow: 0 6px 15px rgba(0, 0, 0, 0.08);
    margin-right: 20px; /* Espacio entre tarjetas */
    overflow: hidden;
    transition: transform 0.3s ease;
    text-align: left;
}

.sticker-card:hover {
    transform: translateY(-5px) scale(1.02);
    box-shadow: 0 10px 20px rgba(0, 0, 0, 0.15);
}

.sticker-card img {
    width: 100%;
    height: 280px; /* Altura fija para consistencia */
    object-fit: cover;
    display: block;
}

.info-card {
    padding: 20px;
}

.info-card h3 {
    color: var(--primary-color);
    margin-bottom: 5px;
}

.info-card p {
    margin-bottom: 15px;
    font-size: 0.95rem;
}

/* Botones de Navegación */
.nav-btn {
    padding: 10px 20px;
    margin: 10px 10px 20px;
    border: none;
    border-radius: 5px;
    background-color: #ccc;
    cursor: pointer;
    font-size: 1rem;
    transition: background-color 0.3s;
    box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
}

.nav-btn:hover {
    background-color: #999;
}

/* --- LEYENDA --- */
.legend {
    background-color: #ffffff;
    padding: 30px;
    border-radius: 12px;
    box-shadow: var(--shadow-light);
    margin-top: 40px;
    text-align: center;
}

.legend h2 {
    margin-bottom: 25px;
    color: var(--primary-color);
}

.legend-item {
    display: flex;
    align-items: center;
    margin-bottom: 15px;
    font-size: 1.1rem;
}

.legend-item span {
    padding: 5px 15px;
    border-radius: 20px;
    font-weight: 700;
    margin-right: 20px;
    display: inline-block;
}

/* Colores de Rareza */
.common { background-color: #d4eaf7; color: #1a527a; }
.rare { background-color: #f9e79f; color: #b7950b; }
.epic { background-color: #d2f7d0; color: #27ae60; }
.mythic { background-color: #d6b3ff; color: #6c3483; }

/* --- FOOTER --- */
footer {
    text-align: center;
    padding: 20px;
    background-color: #333;
    color: #aaa;
    margin-top: 50px;
}

